-- KB-026 distinct service-to-service workload identity and receiver-side authorization.
-- Additive semantic correction only; no historic evidence, finding, assessment or deployment state mutation.
UPDATE risk_knowledge_entries SET problem_json='{"statement":"Internal components trust network location or a shared secret, so compromise of one service grants broad access.","customer_symptom":"An internal agent, MCP tool or gateway request may be authorised merely because it originates on a trusted network or presents a shared secret, allowing a compromised service to reach another service''s resources or actions.","credible_failure_or_attack":"A compromised or impersonated workload, stolen shared bearer credential, wrong-audience token or forwarded service claim may cross an internal service boundary and reach tools, retrieval, jobs or evidence stores without receiving-side identity, audience and operation checks.","affected_assets":["agent and MCP/tool gateways","model and retrieval service endpoints","workload identities, issuer and audience trust policies","short-lived tokens, certificates and credential stores","background jobs and delegated user or tenant context","downstream data, tool actions and audit events"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["distributed agents"],"threat_actor_or_failure_source":"compromised internal workload, impersonated service, reused credential, misconfigured receiver or unsafe delegation","trust_boundary":"Each hop between agent, orchestration, model, retrieval, MCP/tool and downstream services must authenticate the calling workload and authorize the audience, operation and delegated context at the receiver, rather than trusting a private network or model output.","operational_impact":"An unauthorized internal service hop could disclose data or trigger privileged actions across connected tools. The affected route may require immediate isolation, identity revocation, evidence preservation, remedial enforcement and an exact-version accountable human retest."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-026 workload-identity, service, audience, trust-channel or internal-route change","ARL-KB-026 credential lifetime, mutual-authentication or service-policy change","ARL-KB-026 shared-secret exposure, service impersonation or internal identity incident","ARL-KB-026 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"candidate semantic correction; independent practitioner and customer validation required"}', content_digest='6f81fdd9270b7dbe62e50072f599e785ea1bfa05b14062fcc643fd83ed9dcfae', updated_at='2026-10-11' WHERE id='ARL-KB-026';
UPDATE risk_knowledge_checks SET objective='Determine whether each applicable service hop authenticates a distinct attributable workload identity, validates intended issuer/audience and authorizes the operation and delegated context before data disclosure or downstream side effects on the exact assessed build.', method='Document the frozen build, relevant service routes and accountable workload identity/audience policy. Inspect receiving-side authentication, audience and operation checks, credential lifetime/revocation, delegated user or tenant context and asynchronous identity propagation. With explicit written owner authorization, run bounded synthetic permitted-service requests and negative variants for absent, wrong-audience, expired/retired, replayed and confused-deputy identities; correlate authorization, response and downstream state evidence. Source hints alone are not proof of execution, and missing tests do not prove a vulnerability.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-026 exact assessed system, version, environment, service-hop and applicable workload identity and action scope","ARL-KB-026 organisation-approved service identity, issuer, audience, operation and delegated-context matrix with accountable owner and exception record","ARL-KB-026 source or configuration evidence for receiving-side workload identity validation, issuer/audience policy, short credential lifetime, delegation, job propagation and fail-closed paths","ARL-KB-026 bounded positive evidence from owner-authorised synthetic requests that permitted service identities and operations complete within the documented scope","ARL-KB-026 bounded negative evidence of absent, wrong-audience, expired, retired, replayed and confused-deputy service identities denied before data disclosure or downstream side effects","ARL-KB-026 observed runtime identity subject, issuer, audience, policy decision, correlated downstream authorization, response, state and audit events","ARL-KB-026 tester and reviewer identity, written authorisation, roles, timestamps, exact assessed version, evidence digest, unsupported paths, exceptions and accountable human decision"]', pass_condition='KB-026 passes only after accountable human review of exact-build workload identity policy, receiver-side checks, permitted synthetic positive tests, denied negative scenarios before data exposure or side effects, correlated downstream audit evidence and explicitly recorded untested paths or limitations. Source inspection and model instructions alone cannot establish PASS.', fail_condition='KB-026 is a confirmed FAIL only when exact-version evidence reproduces an unauthorized service operation, wrong-audience or retired credential acceptance, forged or replayed identity use, disclosure, unauthorized side effect or demonstrably fail-open receiver. Missing or mismatched runtime tests, source coverage, authorization, identity policy or human review require INCONCLUSIVE / EVIDENCE GAP / REVIEW REQUIRED: block PASS and deployment, but do not claim a confirmed vulnerability.', limitations='A bounded KB-026 review cannot establish the security of untested service routes, runtime deployment changes, future credential rotation, unknown delegates or third-party services. Legal and certification conclusions remain outside ARL''s technical authority.', content_digest='13cb8886f649f3598f7f4757473f7c4b73d7f415d6bed00104eaf33e573aad44', updated_at='2026-10-11' WHERE entry_id='ARL-KB-026';
UPDATE risk_knowledge_solutions SET control_objective='Bind every applicable internal agent, orchestration, model, retrieval and MCP/tool hop to a distinct verified workload identity, intended audience and least-privilege operation, with explicit delegated-context authorization enforced outside the LLM.', recommended_remediation='Replace shared secrets and trusted-network assumptions with attributable workload identities or mutually authenticated channels; verify issuer/audience and operation at each receiver, minimize credential lifetime and privilege, enforce delegation boundaries, rotate/revoke compromised credentials and preserve correlated denial evidence.', default_owner='Platform identity owner', priority='P1', implementation_principles_json='["ARL-KB-026: Distinct short-lived workload identities; verify issuer, intended receiver audience and permitted operation before data access or execution.","ARL-KB-026: Do not accept LLM-generated claims, network locality or a shared secret as standalone service authorization.","ARL-KB-026: Carry separately verified delegated user/tenant context across gateway, worker and tool hops, fail closed if context is missing or invalid.","ARL-KB-026: Deny expired, revoked, wrong-audience and replayed credentials before any downstream side effect."]', monitoring='Record redacted workload subject, issuer, audience, policy version/digest, receiver, operation, decision and correlated downstream effects; alert on wrong audience, expired credential, missing identity and repeated denied requests without logging raw tokens.', containment='Disable affected service/tool route or workload principal, revoke and rotate impacted identities, stop queued side effects, preserve bounded identity and audit traces, and require accountable owner approval before re-enabling.', retest_acceptance_json='["ARL-KB-026: The exact remediated build and workload identity, issuer/audience and operation matrix are approved and version-bound.","ARL-KB-026: Positive permitted synthetic inter-service requests succeed with recorded receiver authorization and expected downstream effects.","ARL-KB-026: Absent, wrong-service, wrong-audience, expired, retired, replayed and confused-deputy variants fail closed before data disclosure or material side effects.","ARL-KB-026: Tester and accountable reviewer record written ROE, exact SHA, evidence digests, omitted routes, residual limitations and human retest decision."]', content_digest='9c41c96c5af6831a243ddb4dfdc08f1ca83d497b97450ed6d609114648c85892', updated_at='2026-10-11' WHERE entry_id='ARL-KB-026';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='362e2ab7654c650c056a376271439251642fa5cb70995856a382e737c5276953', updated_at='2026-10-11' WHERE entry_id='ARL-KB-026';
